+});
+
+test("expands an ascending letter range", () => {
+  assert.deepEqual(expandRange("a-e"), ["a", "b", "c", "d", "e"]);
+});
+
+test("expands a descending letter range", () => {
+  assert.deepEqual(expandRange("e-a"), ["e", "d", "c", "b", "a"]);
+});
+
