{
  "name": "expand-range",
  "version": "1.0.0",
  "description": "Expand ranges like \"1-10\" or \"a-z\" into an array of values",
  "type": "module",
  "main": "src/expand-range.js",
  "exports": "./src/expand-range.js",
  "bin": {
    "expand-range": "bin/expand-range.js"
  },
  "scripts": {
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}

const NUMERIC = /^-?\d+$/;
const LETTER = /^[A-Za-z]$/;
const RANGE = /^(-?\d+|[A-Za-z])-(-?\d+|[A-Za-z])$/;

function numericRange(start, end) {
  const step = start <= end ? 1 : -1;
  const values = [];
  for (let i = start; step > 0 ? i <= end : i >= end; i += step) {
    values.push(i);
  }
  return values;
}

function letterRange(start, end) {
  const from = start.charCodeAt(0);
  const to = end.charCodeAt(0);
  const step = from <= to ? 1 : -1;
  const values = [];
  for (let i = from; step > 0 ? i <= to : i >= to; i += step) {
    values.push(String.fromCharCode(i));
  }
  return values;
}

export function expandRange(range) {
  if (typeof range !== "string") {
    throw new TypeError("range must be a string");
  }

  const match = RANGE.exec(range.trim());
  if (!match) {
    throw new Error(`Invalid range: ${range}`);
  }

  const [, start, end] = match;

  if (NUMERIC.test(start) && NUMERIC.test(end)) {
    return numericRange(Number(start), Number(end));
  }

  if (LETTER.test(start) && LETTER.test(end)) {
    return letterRange(start, end);
  }

  throw new Error(`Range endpoints must both be numeric or both be letters: ${range}`);
}

#!/usr/bin/env node
import { expandRange } from "../src/expand-range.js";

const input = process.argv[2];

if (input === undefined) {
  console.error("Usage: expand-range <range>  e.g. expand-range 1-10");
  process.exit(1);
}

try {
  console.log(JSON.stringify(expandRange(input)));
} catch (error) {
  console.error(error.message);
  process.exit(1);
}

import test from "node:test";
import assert from "node:assert/strict";
import { expandRange } from "../src/expand-range.js";

test("expands an ascending numeric range", () => {
  assert.deepEqual(expandRange("1-5"), [1, 2, 3, 4, 5]);
});

test("expands a descending numeric range", () => {
  assert.deepEqual(expandRange("5-1"), [5, 4, 3, 2, 1]);
});

test("expands negative numeric ranges", () => {
  assert.deepEqual(expandRange("-3-1"), [-3, -2, -1, 0, 1]);
});

test("expands an ascending letter range", () => {
  assert.deepEqual(expandRange("a-e"), ["a", "b", "c", "d", "e"]);
});

test("expands a descending letter range", () => {
  assert.deepEqual(expandRange("e-a"), ["e", "d", "c", "b", "a"]);
});

test("expands a single-value range", () => {
  assert.deepEqual(expandRange("7-7"), [7]);
});

test("ignores surrounding whitespace", () => {
  assert.deepEqual(expandRange("  2-4  "), [2, 3, 4]);
});

test("rejects malformed ranges", () => {
  assert.throws(() => expandRange("abc"), /Invalid range/);
  assert.throws(() => expandRange("1-a"), /both/);
  assert.throws(() => expandRange(10), /string/);
});

